<main class="b64-page"><section class="tool-head"><span class="eyebrow">BASE64 FILE TOOL</span><h1>Base64 File Encoder</h1><p>Encode files to Base64 or decode Base64 data back into a file, directly in your browser.</p></section><section class="tool-card"><div class="tabs"><button class="tab active" data-mode="encode">File → Base64</button><button class="tab" data-mode="decode">Base64 → File</button></div><div id="encodeBox"><label>Choose a file<input id="file" type="file"></label><button id="encode" class="primary">Encode File</button></div><div id="decodeBox" hidden><label>Base64 data<textarea id="base64" placeholder="Paste Base64 data here..."></textarea></label><label>Output filename<input id="filename" value="decoded.bin"></label><button id="decode" class="primary">Decode & Download</button></div><div class="result"><span>Output</span><textarea id="output" readonly placeholder="Encoded Base64 will appear here..."></textarea><div class="row"><button id="copy">Copy Base64</button><span id="status">Ready</span></div></div></section><section class="info-grid"><article><h2>Fast browser processing</h2><p>Files are processed locally in your browser. Nothing needs to be uploaded to the server.</p></article><article><h2>Common uses</h2><p>Useful for API payloads, data URIs, testing, development and transferring small binary files as text.</p></article></section></main>
<style>.b64-page{width:min(900px,calc(100% - 32px));margin:0 auto 70px}.tool-head{text-align:center;padding:48px 0 24px}.eyebrow{color:#5b43ff;font-size:10px;font-weight:900;letter-spacing:1.8px}.tool-head h1{margin:14px 0 8px;font-size:clamp(38px,6vw,56px);line-height:1;letter-spacing:-2.5px}.tool-head p{margin:0;color:#667085;font-size:15px}.tool-card{padding:24px;background:#fff;border:1px solid #e7eaf0;border-radius:24px;box-shadow:0 18px 50px rgba(16,24,40,.07)}.tabs{display:flex;gap:7px;padding:5px;margin-bottom:20px;background:#f4f5f9;border-radius:12px}.tab{flex:1;border:0;border-radius:9px;padding:11px;background:transparent;color:#667085;font-size:10px;font-weight:900;cursor:pointer}.tab.active{background:#fff;color:#5541ff;box-shadow:0 2px 8px rgba(16,24,40,.08)}.tool-card label{display:grid;gap:7px;margin-bottom:13px;color:#344054;font-size:11px;font-weight:800}.tool-card input,.tool-card textarea{box-sizing:border-box;width:100%;padding:12px;border:1px solid #dfe3eb;border-radius:11px;background:#fcfdff;color:#172033;font:12px ui-monospace,SFMono-Regular,Menlo,monospace;outline:0}.tool-card input{height:46px}.tool-card textarea{min-height:210px;resize:vertical;line-height:1.6}.primary{width:100%;height:46px;border:0;border-radius:10px;background:linear-gradient(90deg,#5d46ff,#3e7dff);color:#fff;font-size:10px;font-weight:900;cursor:pointer}.result{margin-top:15px;padding:16px;border:1px solid #e7eaf0;border-radius:14px;background:#fafbff}.result>span{display:block;color:#69738e;font-size:10px;font-weight:800;margin-bottom:8px}.result textarea{background:#fff;min-height:160px}.row{display:flex;justify-content:space-between;align-items:center;margin-top:9px}.row button{padding:9px 13px;border:1px solid #111936;border-radius:9px;background:#111936;color:#fff;font-size:9px;font-weight:900;cursor:pointer}.row span{font-size:10px;color:#69738e}.info-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:18px}.info-grid article{padding:22px;border:1px solid #e7eaf0;border-radius:18px;background:#fff}.info-grid h2{margin:0 0 10px;font-size:17px}.info-grid p{margin:0;color:#667085;font-size:12px;line-height:1.75}@media(max-width:650px){.b64-page{width:calc(100% - 20px)}.tool-card{padding:16px}.tabs{flex-direction:column}.info-grid{grid-template-columns:1fr}}
</style><script>(()=>{const enc=document.getElementById('encodeBox'),dec=document.getElementById('decodeBox'),output=document.getElementById('output'),status=document.getElementById('status');document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>{document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x===b));const e=b.dataset.mode==='encode';enc.hidden=!e;dec.hidden=e;output.value='';status.textContent='Ready'});document.getElementById('encode').onclick=()=>{const f=document.getElementById('file').files[0];if(!f){status.textContent='Choose a file first.';return}const r=new FileReader();r.onload=()=>{const bytes=new Uint8Array(r.result);let binary='';const size=0x8000;for(let i=0;i<bytes.length;i+=size)binary+=String.fromCharCode(...bytes.subarray(i,i+size));output.value=btoa(binary);status.textContent=`Encoded ${f.name} · ${bytes.length.toLocaleString()} bytes`};r.onerror=()=>status.textContent='Could not read the file.';r.readAsArrayBuffer(f)};document.getElementById('decode').onclick=()=>{try{let raw=document.getElementById('base64').value.trim().replace(/^data:.*?;base64,/,'').replace(/\s/g,'');const binary=atob(raw);const bytes=new Uint8Array(binary.length);for(let i=0;i<binary.length;i++)bytes[i]=binary.charCodeAt(i);const blob=new Blob([bytes]);const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=document.getElementById('filename').value.trim()||'decoded.bin';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);status.textContent=`Decoded ${bytes.length.toLocaleString()} bytes`;output.value=''}catch(e){status.textContent='Invalid Base64 data.'}};document.getElementById('copy').onclick=async()=>{if(!output.value){status.textContent='Encode a file first.';return}await navigator.clipboard.writeText(output.value);status.textContent='Base64 copied.'}})();</script>
